class Solution {
  public int smallestDifference(int[] a, int[] b) {
    Arrays.sort(a);
    Arrays.sort(b);
    int i = 0, j = 0;
    long best = Long.MAX_VALUE;
    while (i < a.length && j < b.length) {
      best = Math.min(best, Math.abs((long) a[i] - b[j]));
      if (a[i] < b[j]) {
        i++;
      } else {
        j++;
      }
    }
    return (int) best;
  }
}

class Solution:
    def smallestDifference(self, a: List[int], b: List[int]) -> int:
        a.sort()
        b.sort()
        i = j = 0
        best = float("inf")
        while i < len(a) and j < len(b):
            best = min(best, abs(a[i] - b[j]))
            if a[i] < b[j]:
                i += 1
            else:
                j += 1
        return best

impl Solution {
  pub fn smallest_difference(mut a: Vec<i32>, mut b: Vec<i32>) -> i32 {
    a.sort();
    b.sort();
    let (mut i, mut j) = (0usize, 0usize);
    let mut best = i64::MAX;
    while i < a.len() && j < b.len() {
      best = best.min((a[i] as i64 - b[j] as i64).abs());
      if a[i] < b[j] {
        i += 1;
      } else {
        j += 1;
      }
    }
    best as i32
  }
}

const smallestDifference = (a: number[], b: number[]): number => {
  a.sort((x, y) => x - y);
  b.sort((x, y) => x - y);
  let i = 0;
  let j = 0;
  let best = Infinity;
  while (i < a.length && j < b.length) {
    best = Math.min(best, Math.abs(a[i] - b[j]));
    if (a[i] < b[j]) i++;
    else j++;
  }
  return best;
};
